window.ScripturaLexicons.BDAG_PART_0007 = {source:"BDAG", searchAnchorId:"bdag-search-anchor", entryAnchorId:"bdag-entry-anchor", rowsHtml:"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hagiasmos-bdag\" data-source=\"BDAG\" data-search=\"ἁγιασμός hagiasmos santidade consagração santificação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἁγιασμός</td><td>Substantivo</td><td>santidade; consagração; santificação</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hagioi-bdag\" data-source=\"BDAG\" data-search=\"ἅγιοι hagioi santos pessoas santas veja ἅγιος BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἅγιοι</td><td>Substantivo</td><td>os santos (ver ἅγιος 2d)</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hagion-bdag\" data-source=\"BDAG\" data-search=\"ἅγιον hagion santo coisa santa santuário veja ἅγιος BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἅγιον</td><td>Substantivo</td><td>o que é santo; santuário (ver ἅγιος 2a)</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hagioprepes-bdag\" data-source=\"BDAG\" data-search=\"ἁγιοπρεπής hagioprepes próprio de santo santo digno BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἁγιοπρεπής</td><td>Adjetivo</td><td>próprio de quem é santo; santo</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hagios-bdag\" data-source=\"BDAG\" data-search=\"ἅγιος hagios santo sagrado consagrado puro perfeito Deus Cristo Espírito santos santuário BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἅγιος</td><td>Adjetivo/Substantivo</td><td>santo; sagrado; consagrado; puro</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hagiotes-bdag\" data-source=\"BDAG\" data-search=\"ἁγιότης hagiotes santidade caráter santo pureza moral BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἁγιότης</td><td>Substantivo</td><td>santidade</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hagiophoros-bdag\" data-source=\"BDAG\" data-search=\"ἁγιοφόρος hagiophoros portador coisas santas santo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἁγιοφόρος</td><td>Adjetivo</td><td>portador de coisas santas</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hagiosyne-bdag\" data-source=\"BDAG\" data-search=\"ἁγιωσύνη hagiosyne santidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἁγιωσύνη</td><td>Substantivo</td><td>santidade</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ankale-bdag\" data-source=\"BDAG\" data-search=\"ἀγκάλη ankale braço braços receber nos braços BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀγκάλη</td><td>Substantivo</td><td>braço; braços</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ankistron-bdag\" data-source=\"BDAG\" data-search=\"ἄγκιστρον ankistron anzol BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἄγκιστρον</td><td>Substantivo</td><td>anzol</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ankyra-bdag\" data-source=\"BDAG\" data-search=\"ἄγκυρα ankyra âncora navio esperança BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἄγκυρα</td><td>Substantivo</td><td>âncora</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ankon-bdag\" data-source=\"BDAG\" data-search=\"ἀγκών ankon braço dobrado braço BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀγκών</td><td>Substantivo</td><td>braço dobrado; braço</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-agnaphos-bdag\" data-source=\"BDAG\" data-search=\"ἄγναφος agnaphos pano não apisoado não encolhido novo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἄγναφος</td><td>Adjetivo</td><td>não apisoado; não encolhido; novo</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hagneia-bdag\" data-source=\"BDAG\" data-search=\"ἁγνεία hagneia pureza castidade pureza moral BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἁγνεία</td><td>Substantivo</td><td>pureza; castidade</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hagneuterion-bdag\" data-source=\"BDAG\" data-search=\"ἁγνευτήριον hagneuterion lugar purificação santuário templo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἁγνευτήριον</td><td>Substantivo</td><td>lugar de purificação; santuário</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hagneuo-bdag\" data-source=\"BDAG\" data-search=\"ἁγνεύω hagneuo ser puro pureza alma BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἁγνεύω</td><td>Verbo</td><td>ser puro</td><td><span class=\"source-pill\">BDAG</span></td></tr>", cardsHtml:"<article id=\"entry-hagiasmos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἁγιασμός</h1><div class=\"entry-meta\"><span class=\"greek\">οῦ, ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦hagiasmós⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"> (LXX; PsSol 17:30; Test12Patr. — Diod S 4, 39, 1 tem <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁγισμός\" data-meanings=\"consagração; santificação\">ἁγισμός</span>.)\n<strong>Dedicação pessoal aos interesses da divindade, santidade, consagração, santificação</strong>; o uso em sentido moral para um processo ou, mais frequentemente, seu resultado (o estado de haver sido tornado santo) é peculiar à nossa literatura (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JER.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">Jr 6.16</a> v.l.; TestBenj 10:11).\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰς ἁγιασμόν\" data-meanings=\"para santificação; para consagração\">εἰς ἁγιασμόν</span>, “para consagração” (oposto a <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰς ἀνομίαν\" data-meanings=\"para a iniquidade\">εἰς ἀνομίαν</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.19\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 6.19</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.22\" target=\"_blank\" rel=\"noopener noreferrer\">22</a> (AcThom 121 [Aa II/2, 230, 23]). Oposto a <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀκαθαρσία\" data-meanings=\"impureza\">ἀκαθαρσία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ts 4.7</a>; com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τιμή\" data-meanings=\"honra\">τιμή</span> v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">4</a>, compare v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">3</a>; com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πίστις\" data-meanings=\"fé\">πίστις</span> e <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγάπη\" data-meanings=\"amor\">ἀγάπη</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Tm 2.15</a>; com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰρήνη\" data-meanings=\"paz\">εἰρήνη</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12.14</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν ἁ. πνεύματος\" data-meanings=\"em santificação do Espírito\">ἐν ἁ. πνεύματος</span>, “em consagração pelo Espírito”, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ts 2.13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 1.2</a> (TestLevi 18:7 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πνεῦμα ἁγιασμοῦ\" data-meanings=\"espírito de santificação\">πνεῦμα ἁγιασμοῦ</span>). Cristo é descrito como <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁ.\" data-meanings=\"santificação\">ἁ.</span> com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δικαιοσύνη\" data-meanings=\"justiça\">δικαιοσύνη</span> e <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀπολύτρωσις\" data-meanings=\"redenção\">ἀπολύτρωσις</span> (abstrato pelo concreto, “autor da santidade”; compare a tríade em Did., <em>Gen.</em> 221, 15), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.30\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 1.30</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ποιεῖν τὰ τοῦ ἁ. πάντα\" data-meanings=\"fazer tudo o que pertence à santidade\">ποιεῖν τὰ τοῦ ἁ. πάντα</span>, 1 Cl 30:1; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐγκράτεια ἐν ἁ.\" data-meanings=\"autocontrole em santificação\">ἐγκράτεια ἐν ἁ.</span>, “autocontrole com consagração”, 35:2. — E. Gaugler, “D. Heiligung in d. Ethik des Ap. Pls”, <em>Internat. kirchl. Ztschr.</em> 15, 1925, 100–120; M. Enslin, <em>The Ethics of Paul</em> 1930; S. Djukanovič, <em>Heiligkt u. Heilgg b. Pls</em>, diss. Bern 1939. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅζομαι\" data-meanings=\"reverenciar\">ἅζομαι</span>. TW.\n</p></section>\n</article><article id=\"entry-hagioi-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἅγιοι</h1><div class=\"entry-meta\"><span class=\"greek\">ων, οἱ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦hágioi⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅγιος\" data-meanings=\"santo; sagrado\">ἅγιος</span> 2d.</p></section>\n</article><article id=\"entry-hagion-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἅγιον</h1><div class=\"entry-meta\"><span class=\"greek\">ου, τό</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦hágion⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅγιος\" data-meanings=\"santo; sagrado\">ἅγιος</span> 2a.</p></section>\n</article><article id=\"entry-hagioprepes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἁγιοπρεπής</h1><div class=\"entry-meta\"><span class=\"greek\">ές</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦hagioprepḗs⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n<strong>Adequado/próprio para alguém santo, santo.</strong> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"λόγοι ἁ.\" data-meanings=\"palavras santas\">λόγοι ἁ.</span>, “palavras santas”, 1 Cl 13:3; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δεσμοὶ ἁ.\" data-meanings=\"cadeias próprias de um santo\">δεσμοὶ ἁ.</span>, “cadeias próprias de um santo”, Pol 1:1.\n</p></section>\n</article><article id=\"entry-hagios-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἅγιος</h1><div class=\"entry-meta\"><span class=\"greek\">ία, ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦hágios⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"> Originalmente conceito cultual, da qualidade possuída por coisas e pessoas que podiam aproximar-se de uma divindade (entre os poetas trágicos apenas Téspis, Fgm. 4 p. 833 Nauck² <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"βωμῶν ἁγίων\" data-meanings=\"altares santos\">βωμῶν ἁγίων</span>, mas encontrado desde o séc. V a.C. como termo cultual no jônico e ático, por exemplo <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἱρόν\" data-meanings=\"santuário; coisa sagrada\">ἱρόν</span> Hdt. 2, 41; 44; Pla., <em>Critias</em> 116c; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τόπος\" data-meanings=\"lugar\">τόπος</span> <em>Leg.</em> 904e; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τελεταί\" data-meanings=\"ritos; iniciações\">τελεταί</span> Aristoph., <em>Nub.</em> 304 e Demosth. 25, 11 [<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁγιώταται\" data-meanings=\"santíssimas\">ἁγιώταται</span>]; sobretudo nos mistérios [G. Wobbermin, <em>Rel. gesch. Studien</em> 1896, 59 ss.; compare OGI 721, 1 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τῶν ἁγιωτάτων Ἐλευσῖνι μυστηρίων\" data-meanings=\"dos santíssimos mistérios em Elêusis\">τῶν ἁγιωτάτων Ἐλευσῖνι μυστηρίων</span>]; LXX [H. Gehman, VetusT 4, 1954, 337–348]; LXX, pseudoepígrafos, Fílon, Josefo, apologistas).\n<span class=\"sense-number\">1.</span> Como adjetivo, <strong>relativo a ser dedicado ou consagrado ao serviço de Deus.</strong>\n<strong>a.</strong> No sentido cultual, <strong>dedicado a Deus, santo, sagrado</strong>, isto é, reservado para Deus e seu serviço.\n<strong>α.</strong> De coisas: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁ. πόλις\" data-meanings=\"cidade santa\">ἁ. πόλις</span> de Jerusalém (Appian, <em>Syr.</em> 50 §250: Jerusalém é chamada <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁγιωτάτη πόλις\" data-meanings=\"cidade santíssima\">ἁγιωτάτη πόλις</span> dos judeus; também <em>Mithrid.</em> 106 §498; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.48.2\" target=\"_blank\" rel=\"noopener noreferrer\">Is 48.2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.52.1\" target=\"_blank\" rel=\"noopener noreferrer\">52.1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.66.20\" target=\"_blank\" rel=\"noopener noreferrer\">66.20</a>; 2 Esdr 21:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DAN.3.28\" target=\"_blank\" rel=\"noopener noreferrer\">Dn 3.28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1MA.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Mc 2.7</a> e outros; B-D-F §474, 1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4.5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.53\" target=\"_blank\" rel=\"noopener noreferrer\">27.53</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 11.2</a>; da Jerusalém celestial, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.2\" target=\"_blank\" rel=\"noopener noreferrer\">21.2</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.10\" target=\"_blank\" rel=\"noopener noreferrer\">10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.19\" target=\"_blank\" rel=\"noopener noreferrer\">22.19</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τόπος ἅ.\" data-meanings=\"lugar santo\">τόπος ἅ.</span> do templo (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/2MA.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">2 Mc 2.18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/2MA.8.17\" target=\"_blank\" rel=\"noopener noreferrer\">8.17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/3MA.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">3 Mc 2.14</a>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 6.13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.28\" target=\"_blank\" rel=\"noopener noreferrer\">21.28</a>; mas da vida futura, 1 Cl 5:7, como <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁ ἅ. αἰών\" data-meanings=\"a era santa\">ὁ ἅ. αἰών</span> = <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰὼν μέλλων\" data-meanings=\"era vindoura\">αἰὼν μέλλων</span> (compare a adição à tradução latina de Eclo 17:27, <em>aevum sanctum</em>) B 10:11. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"γῆ ἁ.\" data-meanings=\"terra santa\">γῆ ἁ.</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/2MA.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Mc 1.7</a>; TestJob 33:5) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.33\" target=\"_blank\" rel=\"noopener noreferrer\">At 7.33</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EXO.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Êx 3.5</a>); <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὄρος ἅ.\" data-meanings=\"monte santo\">ὄρος ἅ.</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/WIS.9.8\" target=\"_blank\" rel=\"noopener noreferrer\">Sb 9.8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.14.1\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 14.1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.42.3\" target=\"_blank\" rel=\"noopener noreferrer\">42.3</a> e outros; Appian, <em>Bell. Civ.</em> 1, 1 §2 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸ ὄρος τὸ ἀπὸ τοῦδε κλῃζόμενον ἱερόν\" data-meanings=\"o monte que desde então é chamado sagrado\">τὸ ὄρος τὸ ἀπὸ τοῦδε κλῃζόμενον ἱερόν</span>) do monte da Transfiguração, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pe 1.18</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"σκεύη\" data-meanings=\"vasos; utensílios\">σκεύη</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1ES.8.57\" target=\"_blank\" rel=\"noopener noreferrer\">1 Esd 8.57</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1MA.4.49\" target=\"_blank\" rel=\"noopener noreferrer\">1 Mc 4.49</a>) Ox 840, 14; 21; 29 (ASyn. 150, 112; 114; 116); <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"σκηνή\" data-meanings=\"tabernáculo; tenda\">σκηνή</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9.2</a> (J. Swetnam, CBQ 32, 1970, 205–221, defende a tradução da Vulgata). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"διαθήκη\" data-meanings=\"aliança\">διαθήκη</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DAN.11.28\" target=\"_blank\" rel=\"noopener noreferrer\">Dn 11.28 ss.</a> Theod.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1MA.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Mc 1.15</a>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.72\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1.72</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"γραφαί\" data-meanings=\"Escrituras\">γραφαί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 1.2</a> (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1MA.12.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Mc 12.9</a>; Fílon, <em>Rer. Div. Her.</em> 159); <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εὐαγγέλιον\" data-meanings=\"evangelho\">εὐαγγέλιον</span> AcPlCor 2:36; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"λόγος\" data-meanings=\"palavra\">λόγος</span> 1 Cl 13:3; 56:3; Dg 7:2 (compare Herm. Wr. 1:18 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁ θεὸς εἶπεν ἁγίῳ λόγῳ\" data-meanings=\"Deus falou por palavra santa\">ὁ θεὸς εἶπεν ἁγίῳ λόγῳ</span>). Como os cristãos são chamados “santos” (veja 2dβ), sua <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κλῆσις\" data-meanings=\"chamado; vocação\">κλῆσις</span> também é <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁ.\" data-meanings=\"santa\">ἁ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Tm 1.9</a>; assim também a <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐντολή\" data-meanings=\"mandamento\">ἐντολή</span> dada a eles, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pe 2.21</a>. Sua comunidade forma uma <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐκκλησία ἁ.\" data-meanings=\"igreja santa\">ἐκκλησία ἁ.</span> ITr ins.; Hv 1, 1, 6; 1, 3, 4; compare 4, 1, 3, bem como um <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἱεράτευμα ἅ.\" data-meanings=\"sacerdócio santo\">ἱεράτευμα ἅ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 2.5</a> e um <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἔθνος ἅ.\" data-meanings=\"nação santa\">ἔθνος ἅ.</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/WIS.17.2\" target=\"_blank\" rel=\"noopener noreferrer\">Sb 17.2</a>) v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">9</a>. Para <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"φίλημα ἅ.\" data-meanings=\"beijo santo\">φίλημα ἅ.</span>, veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"φίλημα\" data-meanings=\"beijo\">φίλημα</span>. — <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πίστις\" data-meanings=\"fé\">πίστις</span> é <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁγιωτάτη\" data-meanings=\"santíssima\">ἁγιωτάτη</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JUD.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Jd 20</a> (para o superlativo compare Pla., <em>Leg.</em> 729e; Diod S 3, 44, 2 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἱερὸν ἁγιώτατον\" data-meanings=\"templo excepcionalmente santo\">ἱερὸν ἁγιώτατον</span>; SIG 339, 14; 768, 16 [31 a.C.]; Jos., <em>Ant.</em> 16, 115; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁγιώτατος θεός\" data-meanings=\"Deus santíssimo\">ἁγιώτατος θεός</span>: OGI 755, 1; 756, 3; compare PGM 4, 668; da sinagoga CIJ 754; 781; 867).\n<strong>β.</strong> De seres humanos e transcendentes. <strong>א.</strong> De seres humanos consagrados a Deus, <strong>santos, puros, reverentes</strong> (CB I/2, 386 nº 232, 8 [início séc. III d.C.] de um gentio: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Γάϊος, ὡς ἅγιος, ὡς ἀγαθός\" data-meanings=\"Gaio, como santo, como bom\">Γάϊος, ὡς ἅγιος, ὡς ἀγαθός</span>); profetas (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/WIS.11.1\" target=\"_blank\" rel=\"noopener noreferrer\">Sb 11.1</a>; compare <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅ. Ἀβράμ\" data-meanings=\"santo Abraão\">ἅ. Ἀβράμ</span> Did., <em>Gen.</em> 228, 23) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.70\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1.70</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">At 3.21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pe 3.2</a>; João Batista (com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δίκαιος\" data-meanings=\"justo\">δίκαιος</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6.20</a>; apóstolos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 3.5</a>; de Policarpo, EpilMosq 1; 3; 5; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἱ ἅ. γυναῖκες\" data-meanings=\"as santas mulheres\">αἱ ἅ. γυναῖκες</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 3.5</a>. Israel, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"λαὸς ἅ.\" data-meanings=\"povo santo\">λαὸς ἅ.</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.62.12\" target=\"_blank\" rel=\"noopener noreferrer\">Is 62.12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/SIR.49.12\" target=\"_blank\" rel=\"noopener noreferrer\">Eclo 49.12</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DAN.7.27\" target=\"_blank\" rel=\"noopener noreferrer\">Dn 7.27</a>; PsSol 17) 1 Cl 8:3; compare B 14:6; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πᾶν ἄρσεν τῷ κυρίῳ\" data-meanings=\"todo macho [consagrado] ao Senhor\">πᾶν ἄρσεν τῷ κυρίῳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2.23</a>. — Os cristãos (Orígenes, <em>C. Cels.</em> 3, 60, 16): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅ. ἔσεσθε\" data-meanings=\"sereis santos\">ἅ. ἔσεσθε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 1.16a</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/LEV.19.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lv 19.2</a>). Carismáticos (?) (assim E. Käsemann, <em>Beiträge zur Hist. Theol.</em> 9, 1933, 146 n. 5) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.26\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 1.26</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀδελφοὶ ἅ.\" data-meanings=\"irmãos santos\">ἀδελφοὶ ἅ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3.1</a>; seus filhos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 7.14</a> (G. Delling, <em>Studien zum NT</em>, 1970, 270–280, 281–287 = <em>Festschrift Fascher</em>, 84–93; J. Blinzler em <em>Festschrift Schmid</em>, 1963, 23–41; K. Aland, <em>Die Stellung d. Kinder in d. frühen christl. Gemeinden u. ihre Taufe</em>, 1967, 13–17). Presbíteros, IMg 3:1. Com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄμωμος\" data-meanings=\"irrepreensível\">ἄμωμος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 1.4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.27\" target=\"_blank\" rel=\"noopener noreferrer\">5.27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 1.22</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅ. ἐν ἀναστροφῇ\" data-meanings=\"santo no procedimento\">ἅ. ἐν ἀναστροφῇ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 1.15</a>, compare D 10:6.\n<strong>ב.</strong> De anjos, <strong>santos</strong> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JOB.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Jó 5.1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/TOB.11.14\" target=\"_blank\" rel=\"noopener noreferrer\">Tb 11.14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/TOB.12.15\" target=\"_blank\" rel=\"noopener noreferrer\">12.15</a>; compare Bousset, <em>Rel.</em>³ 321; Cat. Cod. Astr. VIII/2 p. 176, 19; PGM 4, 668; AscIs 3, 16) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 8.38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9.26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.22\" target=\"_blank\" rel=\"noopener noreferrer\">At 10.22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 14.10</a>; 1 Cl 39:7; Hv 2, 2, 7; 3, 4, 1 s.; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν ἁ. μυριάσιν αὐτοῦ\" data-meanings=\"com suas santas miríades\">ἐν ἁ. μυριάσιν αὐτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JUD.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Jd 14</a> (com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄγγελος\" data-meanings=\"anjo\">ἄγγελος</span> P72; compare En 1:9).\n<strong>ג.</strong> De Cristo, <strong>santo</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸν ἅγιον παῖδά σου\" data-meanings=\"teu santo servo\">τὸν ἅγιον παῖδά σου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.27\" target=\"_blank\" rel=\"noopener noreferrer\">At 4.27</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.30\" target=\"_blank\" rel=\"noopener noreferrer\">30</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸ γεννώμενον ἅ. κληθήσεται\" data-meanings=\"o que nascer será chamado santo\">τὸ γεννώμενον ἅ. κληθήσεται</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1.35</a>; GJs 11:3 (<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅ.\" data-meanings=\"santo\">ἅ.</span> pertence ao predicativo).\n<strong>ד.</strong> De Deus (Aristoph., <em>Av.</em> 522; Pla., <em>Soph.</em> 249a; OGI 262, 25; 378, 1 [19 d.C.] <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"θεῷ ἁγίῳ ὑψίστῳ\" data-meanings=\"ao Deus santo altíssimo\">θεῷ ἁγίῳ ὑψίστῳ</span>; 590, 1; 620, 2 [98 d.C.]; UPZ 79, 22 [159 a.C.] de Ísis; semelhantemente POxy 1380, 34; 36; 89; IDefixWünsch 4, 10 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸν ἅ. Ἑρμῆν\" data-meanings=\"o santo Hermes\">τὸν ἅ. Ἑρμῆν</span>; Herm. Wr. 1, 31; PGM 1, 198; 3, 312; 4, 851; 2093; outros exemplos em Wobbermin 70; Cumont³ 266; LXX; Fílon, <em>Sacr. Abel.</em> 101; SibOr 3, 478): <strong>santo</strong> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.17.11\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 17.11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 1.16b</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/LEV.19.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lv 19.2</a>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 4.8</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">Is 6.3</a>; TestAbr A 3, p. 79, 19 [Stone p. 6]; ParJer 9:3). A tríplice repetição de <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅγιος\" data-meanings=\"santo\">ἅγιος</span> serve para intensificar a ideia, como o duplo <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"καλὸν καλόν\" data-meanings=\"belíssimo; indescritivelmente belo\">καλὸν καλόν</span> em Theocr. 8, 73; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 6.10</a>. Do nome de Deus (LXX; PGM 4, 1190; 13, 638), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.49\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1.49</a>; 1 Cl 64.\n<strong>ה.</strong> Do espírito: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸ πνεῦμα τὸ ἅγιον\" data-meanings=\"o Espírito Santo\">τὸ πνεῦμα τὸ ἅγιον</span>, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸ ἅγιον πνεῦμα\" data-meanings=\"o Santo Espírito\">τὸ ἅγιον πνεῦμα</span> ou <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πν. ἅ.\" data-meanings=\"Espírito Santo\">πν. ἅ.</span>; veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πνεῦμα\" data-meanings=\"espírito\">πνεῦμα</span> 5c.\n<strong>b.</strong> Com matiz para <strong>santo = puro, perfeito, digno de Deus</strong> (Stephan. Byz. s.v. Παλική: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὅρκος ἅγιος\" data-meanings=\"juramento sagrado\">ὅρκος ἅγιος</span>): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"θυσία\" data-meanings=\"sacrifício\">θυσία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 12.1</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀναστροφαί\" data-meanings=\"procedimentos; condutas\">ἀναστροφαί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pe 3.11</a>; da lei divina, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 7.12</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀπαρχή\" data-meanings=\"primícias\">ἀπαρχή</span> (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EZK.48.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ez 48.9 ss.</a>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 11.16a</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ναός\" data-meanings=\"templo\">ναός</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.10.4\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 10.4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.17.7\" target=\"_blank\" rel=\"noopener noreferrer\">17.7</a> e outros; Jos., <em>Bell.</em> 7, 379; compare <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἱερὸν ἅ.\" data-meanings=\"santuário santo\">ἱερὸν ἅ.</span>: Hdt. 2, 41; Diod S 5, 72, 3; 15, 14, 3; Paus. 10, 32, 13) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 3.17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 2.21</a>.\n<span class=\"sense-number\">2.</span> Usado como <strong>substantivo puro: o santo (coisa, pessoa).</strong>\n<strong>a.</strong> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅγιον, ου, τό\" data-meanings=\"o que é santo; coisa santa\">ἅγιον, ου, τό</span> <strong>aquilo que é santo.</strong>\n<strong>α.</strong> Concreto, <strong>carne sacrificial</strong> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/LEV.22.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lv 22.14</a>; também concretamente <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"θύειν τὸ ἱερόν\" data-meanings=\"sacrificar a coisa sagrada\">θύειν τὸ ἱερόν</span> na 67ª carta de Apolônio de Tiana [Philostrat. I 363, 30 K.]): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μὴ δῶτε τὸ ἅ. τοῖς κυσίν\" data-meanings=\"não deis o que é santo aos cães\">μὴ δῶτε τὸ ἅ. τοῖς κυσίν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7.6</a>; compare D 9:5; 1QS 9:17.\n<strong>β.</strong> <strong>Santuário</strong> (OGI 56, 59 [239 a.C.]; UPZ 119, 12 [156 a.C.]; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/NUM.3.38\" target=\"_blank\" rel=\"noopener noreferrer\">Nm 3.38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EZK.45.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ez 45.18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1ES.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Esd 1.5</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1MA.10.42\" target=\"_blank\" rel=\"noopener noreferrer\">1 Mc 10.42</a>; Fílon, <em>Leg. All.</em> 3, 125; Jos., <em>Ant.</em> 3, 125): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸ ἅ. κοσμικόν\" data-meanings=\"o santuário terreno\">τὸ ἅ. κοσμικόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9.1</a>.\n<strong>b.</strong> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅγια, ων, τά\" data-meanings=\"santuário; lugares santos\">ἅγια, ων, τά</span> <strong>santuário</strong> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JDT.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Jt 4.12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JDT.16.20\" target=\"_blank\" rel=\"noopener noreferrer\">16.20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1MA.3.43\" target=\"_blank\" rel=\"noopener noreferrer\">1 Mc 3.43</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1MA.3.59\" target=\"_blank\" rel=\"noopener noreferrer\">59</a> e outros; Fílon, <em>Fuga</em> 93 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οἷς ἡ τῶν ἁγίων ἀνάκειται λειτουργία\" data-meanings=\"aos quais é confiado o serviço do santuário\">οἷς ἡ τῶν ἁγίων ἀνάκειται λειτουργία</span>; Jos., <em>Bell.</em> 2, 341): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8.2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.24\" target=\"_blank\" rel=\"noopener noreferrer\">9.24 s.</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">13.11</a>. Também a parte frontal ou externa do templo, <strong>Lugar Santo</strong> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1KI.8.8\" target=\"_blank\" rel=\"noopener noreferrer\">3 Re 8.8</a>; Fílon, <em>Rer. Div. Her.</em> 226), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9.2</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὰ ἅ.\" data-meanings=\"o santuário\">τὰ ἅ.</span> do santuário celestial (SibOr 3, 308), v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.19\" target=\"_blank\" rel=\"noopener noreferrer\">10.19</a>. — <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"(τὰ) ἅγια (τῶν) ἁγίων\" data-meanings=\"(o) Santo dos Santos\">(τὰ) ἅγια (τῶν) ἁγίων</span> <strong>Santo dos Santos</strong> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1KI.8.6\" target=\"_blank\" rel=\"noopener noreferrer\">3 Re 8.6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/2CH.4.22\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cr 4.22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/2CH.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">5.7</a>; GrBar ins. 2; Fílon, <em>Leg. All.</em> 2, 56; compare Polyb. 16, 12, 7 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸ τοῦ Διὸς ἄβατον\" data-meanings=\"o recinto inacessível de Zeus\">τὸ τοῦ Διὸς ἄβατον</span>; formado como <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κακὰ κακῶν\" data-meanings=\"males dos males\">κακὰ κακῶν</span> Sófocles, <em>Oed. C.</em> 1238; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄρρητ’ ἀρρήτων\" data-meanings=\"inefáveis dos inefáveis\">ἄρρητ’ ἀρρήτων</span> <em>Oed. R.</em> 465; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἔσχατα ἐσχάτων\" data-meanings=\"extremos dos extremos\">ἔσχατα ἐσχάτων</span> Ael. Aristid. 46 p. 260 D.; B-D-F §141, 8; 245, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9.3</a>; IPhld 9:1; GJs 8:3; 13:2; 15:3. Dos cristãos, 1 Cl 29:3 (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/2CH.31.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cr 31.14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EZK.48.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ez 48.12</a>).\n<strong>c.</strong> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅγιος, ου, ὁ\" data-meanings=\"o Santo\">ἅγιος, ου, ὁ</span> <strong>o Santo.</strong> <strong>α.</strong> De Deus (En 14:1; 97:6; 98:6; 104:9), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Jo 2.20</a> (β também é provável; veja O. Piper, JBL 66, 1947, 437–451). <strong>β.</strong> De Cristo: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁ ἅ.\" data-meanings=\"o Santo\">ὁ ἅ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 3.7</a>; 1 Cl 23:5; Dg 9:2; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁ ἅ. καὶ δίκαιος\" data-meanings=\"o Santo e Justo\">ὁ ἅ. καὶ δίκαιος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">At 3.14</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁ ἅ. τοῦ θεοῦ\" data-meanings=\"o Santo de Deus\">ὁ ἅ. τοῦ θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1.24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4.34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.69\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 6.69</a> (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.105.16\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 105.16</a>, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁ ἅ. κυρίου\" data-meanings=\"o santo do Senhor\">ὁ ἅ. κυρίου</span> de Arão). <strong>γ.</strong> Do mártir Policarpo, EpilMosq 2 (dos salmistas, Did., <em>Gen.</em> 60, 18).\n<strong>d.</strong> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅγιοι, ων, οἱ\" data-meanings=\"os santos\">ἅγιοι, ων, οἱ</span> <strong>os santos.</strong> <strong>α.</strong> De anjos (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ZEC.14.5\" target=\"_blank\" rel=\"noopener noreferrer\">Zc 14.5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.88.6\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 88.6</a>; En 1:9; PsSol 17:43; PGM 1, 198; 4, 1345; 1347). Para <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ts 3.13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ts 1.10</a>; D 16:7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 1.12</a> (compare 1QS 11:7 s.), β também é provável. <strong>β.</strong> <strong>Crentes, seguidores leais, santos</strong>, de cristãos como consagrados a Deus (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Is 4.3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/TOB.8.15\" target=\"_blank\" rel=\"noopener noreferrer\">Tb 8.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.33.10\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 33.10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DAN.7.18\" target=\"_blank\" rel=\"noopener noreferrer\">Dn 7.18</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DAN.7.21\" target=\"_blank\" rel=\"noopener noreferrer\">21</a>): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 9.13</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.32\" target=\"_blank\" rel=\"noopener noreferrer\">32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.27\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 8.27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.13\" target=\"_blank\" rel=\"noopener noreferrer\">12.13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.25\" target=\"_blank\" rel=\"noopener noreferrer\">15.25</a> (Ltzm., exc. ad loc. sobre a comunidade primitiva em Jerusalém); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 6.1 s.</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 1.1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 2.19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">3.8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.22\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 4.22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 1.4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Tm 5.10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6.10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 22.21</a> v.l. (veja R. Borger, TRu 52, 1987, 56 s.); D 16:7 talvez; 1 Cl 46:2; Hv 1, 1, 9 e outros; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κλητοὶ ἅ.\" data-meanings=\"chamados santos\">κλητοὶ ἅ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 1.7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 1.2</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οἱ ἅ. αὐτοῦ\" data-meanings=\"os seus santos\">οἱ ἅ. αὐτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.26\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 1.26</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 9.13</a>; Hv 3, 8, 8; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οἱ ἅ. καὶ πιστοὶ αὐτοῦ\" data-meanings=\"seus santos e fiéis\">οἱ ἅ. καὶ πιστοὶ αὐτοῦ</span> ISm 1:2. <strong>γ.</strong> De outras pessoas especialmente próximas de Deus (Dionys. Soph., Ep. 70 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"σωφροσύνη … προσήγαγέ σε θεῷ … τοῖς ἁγίοις παρέστησεν\" data-meanings=\"a temperança te conduziu a Deus e te colocou entre os santos\">σωφροσύνη … προσήγαγέ σε θεῷ … τοῖς ἁγίοις παρέστησεν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.52\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27.52</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 18.20</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.24\" target=\"_blank\" rel=\"noopener noreferrer\">24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 2.19</a>. — F. J. Dölger, <em>ΙΧΘΥΣ</em> 1910, 180–183; W. Link, <em>De vocis ‘sanctus’ usu pagano</em>, diss. Königsberg 1910; A. Fridrichsen, <em>Hagios-Qadoš</em> 1916; E. Williger, <em>Hagios</em> 1922; J. Dillersberger, <em>Das Heilige im NT</em> 1926; H. Delehaye, <em>Sanctus</em> 1927²; 1933; R. Asting, <em>D. Heiligkeit im Urchristentum</em> 1930; U. Bunzel, <em>D. Begriff der Heiligkeit im AT</em>, diss. Breslau 1914; J. Hänel, <em>D. Religion d. Heiligkeit</em> 1931; P. Chantraine/O. Masson, <em>Debrunner Festschr.</em>, 1954, 85–107; F. Nötscher, <em>Vom Alten zum NT</em>, 1962, 126–174 (Qumran); S. Woodward, JETS 24, 1981, 107–116 (Qumran mostra transição da associação do termo “santos” com seres celestiais para seres humanos; veja 1QS 5:6 s.; 8:5 e 8). — B. 1475. EDNT. DDD 1359–1364. <em>New Docs</em> 4, 111. DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅζομαι\" data-meanings=\"reverenciar\">ἅζομαι</span>. M-M. TW. Sv.\n</p></section>\n</article><article id=\"entry-hagiotes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἁγιότης</h1><div class=\"entry-meta\"><span class=\"greek\">ητος, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦hagiótēs⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n<strong>Santidade</strong> (escólio a Aristoph., <em>Plut.</em> 682; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/2MA.15.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Mc 15.2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.28.2\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 28.2</a> numa tradução de Field, <em>Hexapla</em>; TestLevi 3:4 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὑπεράνω πάσης ἁγιότητος\" data-meanings=\"acima de toda santidade\">ὑπεράνω πάσης ἁγιότητος</span>; Did., <em>Gen.</em> 211, 18; título honorífico bizantino, compare Preis. III 183): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μεταλαβεῖν τῆς ἅ.\" data-meanings=\"participar de sua santidade; de seu caráter santo\">μεταλαβεῖν τῆς ἅ.</span>, “participar de seu caráter santo”, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12.10</a>. De pureza moral, com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰλικρίνεια\" data-meanings=\"sinceridade; pureza\">εἰλικρίνεια</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 1.12</a> v.l. (por <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁπλότης\" data-meanings=\"simplicidade; sinceridade\">ἁπλότης</span>); Hv 3, 7, 3 v.l. (por <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁγνότης\" data-meanings=\"pureza\">ἁγνότης</span>). — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅζομαι\" data-meanings=\"reverenciar\">ἅζομαι</span>. M-M.\n</p></section></article><article id=\"entry-hagiophoros-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἁγιοφόρος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦hagiophóros⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n<strong>Portador de coisas santas</strong> (vasos cultuais em procissões), de pessoas (<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁγιαφόρος\" data-meanings=\"portador de coisas santas\">ἁγιαφόρος</span> IG III, 162, de uma pessoa envolvida no culto de Ísis); no uso cristão apenas figuradamente (compare Plut., <em>Mor.</em> 352b: os <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἱεραφόροι\" data-meanings=\"portadores de objetos sagrados\">ἱεραφόροι</span> no culto de Ísis são os que trazem em suas almas, como num receptáculo ou adorno, o ensinamento sobre os deuses, purificado de toda superstição), com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ναοφόροι\" data-meanings=\"portadores do templo\">ναοφόροι</span> e outros, IEph 9:2. Da igreja, ISm ins.; compare Lghtf. ad loc. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"φέρω\" data-meanings=\"carregar; levar\">φέρω</span> A, 1189.\n</p></section></article><article id=\"entry-hagiosyne-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἁγιωσύνη</h1><div class=\"entry-meta\"><span class=\"greek\">ης, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦hagiōsúnē⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Também <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁγιοσύνη\" data-meanings=\"variante de ἁγιωσύνη\">ἁγιοσύνη</span>. Herodian. Gr. I 335; 18; escólio [Platão] <em>Axioch.</em> 371d; LXX Salmos e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/2MA.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Mc 3.12</a>; Pel.-Leg. p. 10, 2; AcThom 58; 97; 104 e outros [Aa II/2, 175, 15; 210, 10; 217, 5]; título honorífico bizantino Preis. III 183; PMeyer 24, 2.) <strong>Santidade.</strong> De Cristo, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κατὰ πνεῦμα ἁγιωσύνης\" data-meanings=\"segundo o espírito de santidade\">κατὰ πνεῦμα ἁγιωσύνης</span> (<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πνεῦμα ἅγιον\" data-meanings=\"Espírito Santo\">πνεῦμα ἅγιον</span> como TestLevi 18:11; compare 1QS 4:21; 9:3), intensificado “Espírito Santo” (oposto a <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κατὰ σάρκα\" data-meanings=\"segundo a carne\">κατὰ σάρκα</span> [idioma semítico, B. Schneider, <em>Biblica</em> 48, 1967, 380]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 1.4</a>. Dos cristãos, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐπιτελεῖν ἁγιωσύνην\" data-meanings=\"aperfeiçoar a santidade\">ἐπιτελεῖν ἁγιωσύνην</span>, “aperfeiçoar a santidade = tornar-se perfeitamente santo”, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 7.1</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν ἁγιωσύνη\" data-meanings=\"em santidade\">ἐν ἁγιωσύνη</span> (AcThom 85; 86 [Aa II/2, 201, 14 s.; 202, 6]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ts 3.13</a>. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅζομαι\" data-meanings=\"reverenciar\">ἅζομαι</span> §2. M-M. s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁγιότης\" data-meanings=\"santidade\">ἁγιότης</span>. TW.\n</p></section></article><article id=\"entry-ankale-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγκάλη</h1><div class=\"entry-meta\"><span class=\"greek\">ης, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦ankálē⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Trágicos, Hdt. e outros; inscrições, papiros, LXX, principalmente plural.) <strong>O braço dobrado como para receber algo, braço.</strong> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δέξασθαι εἰς τὰς ἀ.\" data-meanings=\"receber nos braços\">δέξασθαι εἰς τὰς ἀ.</span>, “receber nos braços” (Jos., <em>Ant.</em> 8, 28 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸ παιδίον … εἰς τὰς ἀ. μου τίθησι\" data-meanings=\"coloca a criança em meus braços\">τὸ παιδίον … εἰς τὰς ἀ. μου τίθησι</span>; OGI 56, 60, de uma imagem cultual, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὶς τῶν ἱερέων οἴσει ἐν ταῖς ἀγκάλαις\" data-meanings=\"um dos sacerdotes a levará nos braços\">τὶς τῶν ἱερέων οἴσει ἐν ταῖς ἀγκάλαις</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2.28</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 9.36</a> usa <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐναγκαλίσασθαι\" data-meanings=\"tomar nos braços\">ἐναγκαλίσασθαι</span>). — DELG s.v. ἀγκ-. M-M.\n</p></section></article><article id=\"entry-ankistron-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄγκιστρον</h1><div class=\"entry-meta\"><span class=\"greek\">ου, τό</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦ánkistron⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Homero e outros; LXX, por exemplo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.19.8\" target=\"_blank\" rel=\"noopener noreferrer\">Is 19.8</a>) <strong>anzol.</strong> <strong>a.</strong> Literalmente, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"βάλλειν ἄ. εἰς θάλασσαν\" data-meanings=\"lançar um anzol ao mar\">βάλλειν ἄ. εἰς θάλασσαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17.27</a>. <strong>b.</strong> Figuradamente (Polyaenus, <em>Exc.</em> 1 p. 431, 10 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"χρυσοῖς ἀγκίστροις\" data-meanings=\"com anzóis de ouro\">χρυσοῖς ἀγκίστροις</span>, para “pescar” com anzóis de ouro), <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐμπεσεῖν εἰς τὰ ἄ. τῆς κενοδοξίας\" data-meanings=\"cair nos anzóis da vanglória\">ἐμπεσεῖν εἰς τὰ ἄ. τῆς κενοδοξίας</span>, “ser apanhado nos anzóis do erro”, IMg 11. — B. 897; 899. DELG s.v. ἀγκ-.\n</p></section></article><article id=\"entry-ankyra-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄγκυρα</h1><div class=\"entry-meta\"><span class=\"greek\">ας, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦ánkura⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Termo náutico, literal e figurado: Alceu e outros; SIG² 588, 168; 171; PCairZen 782a V, 64 [séc. III a.C.]; PColZen 43, 6 [séc. III a.C.]; PLond III, 1164h, 9 p. 164; V, 1714, 2; Jos., <em>Vi.</em> 167; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JER.52.18\" target=\"_blank\" rel=\"noopener noreferrer\">Jr 52.18</a> Sym. em sentido especial.) <strong>Âncora de navio, âncora.</strong> <strong>a.</strong> Literalmente: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ῥίπτειν ἀ.\" data-meanings=\"lançar uma âncora\">ῥίπτειν ἀ.</span>, “soltar/largar uma âncora”, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.29\" target=\"_blank\" rel=\"noopener noreferrer\">At 27.29</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. ἐκτείνειν\" data-meanings=\"estender uma âncora\">ἀ. ἐκτείνειν</span>, “lançar/estender uma âncora”, v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.30\" target=\"_blank\" rel=\"noopener noreferrer\">30</a> (Breusing 195; L. Casson, <em>Ships and Seamanship in the Ancient World</em>, 1971, 256); <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. περιαιρεῖν\" data-meanings=\"retirar as âncoras\">ἀ. περιαιρεῖν</span> v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.40\" target=\"_blank\" rel=\"noopener noreferrer\">40</a> (veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"περιαιρέω\" data-meanings=\"retirar; remover\">περιαιρέω</span> 1). <strong>b.</strong> Figuradamente (Eur., <em>Hec.</em> 80 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄ. οἴκων\" data-meanings=\"âncora da casa\">ἄ. οἴκων</span>; Soph., Fgm. 623 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄ. βίου\" data-meanings=\"âncora da vida\">ἄ. βίου</span>; Heliod. 7, 25, 4 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πᾶσα ἐλπίδος ἄ.\" data-meanings=\"toda âncora de esperança\">πᾶσα ἐλπίδος ἄ.</span>; IG XII, VII 123b, 3 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄ. γήρως\" data-meanings=\"âncora da velhice\">ἄ. γήρως</span>) da esperança (Marinus, <em>Vi. Procli</em> 29): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἥν ὡς ἄγκυραν ἔχομεν τῆς ψυχῆς\" data-meanings=\"a qual temos como âncora da alma\">ἥν ὡς ἄγκυραν ἔχομεν τῆς ψυχῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.19\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6.19</a> (P. Stumpf, RAC I 440–443; C. Spicq, StTh 3, 1949, 185–187). — B. 737. DELG s.v. ἀγκ-. M-M.\n</p></section></article><article id=\"entry-ankon-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγκών</h1><div class=\"entry-meta\"><span class=\"greek\">ῶνος, ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦ankṓn⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Homero e outros; papiros, LXX; Jos., <em>Ant.</em> 17, 187; TestSol 4:5 P e outros manuscritos; Jos., <em>Ant.</em> 17, 187.) <strong>O braço dobrado, braço.</strong> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἴρειν τινὰ τῶν ἀ.\" data-meanings=\"erguer alguém pelos braços\">αἴρειν τινὰ τῶν ἀ.</span>, “erguer alguém pelos braços”, Hv 1, 4, 3. — B. 238. DELG s.v. ἀγκ-.\n</p></section></article><article id=\"entry-agnaphos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄγναφος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦ágnaphos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(<em>Peripl. Eryth.</em> c. 6; Moeris p. 31 sob <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄκναπτον\" data-meanings=\"não apisoado\">ἄκναπτον</span>; Thom. Mag. p. 12, 14; PCairZen 92, 16 [séc. III a.C.]; PHamb 10, 32; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κιτῶνα [χιτῶνα] ἄγναφον\" data-meanings=\"túnica de tecido não apisoado\">κιτῶνα [χιτῶνα] ἄγναφον</span>: BGU 1666, 13 [séc. I d.C.]; PLond II, 193 verso, 22 p. 246 [séc. II d.C.].) <strong>Relativo a pano recém-saído do tear, não apisoado, não encolhido, sem goma, novo</strong> (veja P. Meyer sobre o papiro de Hamburgo acima): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐπίβλημα ῥάκους ἀγνάφου\" data-meanings=\"remendo de pano novo\">ἐπίβλημα ῥάκους ἀγνάφου</span>, “remendo de pano novo” (não deve ser traduzido “não branqueado”), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9.16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 2.21</a>. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κνάπτω\" data-meanings=\"cardar; apisoar pano\">κνάπτω</span>. M-M.\n</p></section></article><article id=\"entry-hagneia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἁγνεία</h1><div class=\"entry-meta\"><span class=\"greek\">ας, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦hagneía⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Sófocles, <em>Oed. R.</em> 864 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁ. λόγων ἔργων τε πάντων\" data-meanings=\"pureza de todas as palavras e ações\">ἁ. λόγων ἔργων τε πάντων</span>; Platão; inscrições [por exemplo, de Epidauro em Teofrasto, <em>De Pietate</em> 9, 11, e Porfírio, <em>Abst.</em> 2, 19 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁγνὸν χρὴ ναοῖο θυώδεος ἐντὸς ἰόντα ἔμμεναι· ἁγνεία δ’ ἐστὶ φρονεῖν ὅσια\" data-meanings=\"quem entra no templo fragrante deve ser puro; pureza é pensar coisas santas\">ἁγνὸν χρὴ ναοῖο θυώδεος ἐντὸς ἰόντα ἔμμεναι· ἁγνεία δ’ ἐστὶ φρονεῖν ὅσια</span>; ISyriaW 2034; 2203]; papiros; LXX [de pureza cultual]; TestJos 10:2; AscIs 3:21; EpArist; Fílon; Josefo; Mel., <em>P.</em> 49, 350.) <strong>A qualidade da pureza moral, pureza</strong>; de uma mente pura (veja a inscrição de Epidauro acima; Jos., <em>Ant.</em> 19, 331), especificamente <strong>castidade</strong> (Diod S 10, 21, 2 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁγνεία τ. σώματος\" data-meanings=\"pureza do corpo\">ἁγνεία τ. σώματος</span>; Fílon, <em>Abr.</em> 98 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁ. τῆς γυναικός\" data-meanings=\"castidade da mulher\">ἁ. τῆς γυναικός</span>; Jos., <em>Ant.</em> 3, 78): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν πάσῃ ἁ.\" data-meanings=\"em toda pureza\">ἐν πάσῃ ἁ.</span>, “com toda propriedade”, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Tm 5.2</a>. Com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πίστις\" data-meanings=\"fé\">πίστις</span> e <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγάπη\" data-meanings=\"amor\">ἀγάπη</span> Pol 4:2. Com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δικαιοσύνη\" data-meanings=\"justiça\">δικαιοσύνη</span> (assim também ISmyrnaMcCabe 1, 15) Hs 9, 16, 7. Com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"σεμνότης\" data-meanings=\"dignidade; seriedade\">σεμνότης</span> (Diod S 4, 24, 5) Hs 5, 6, 5. Com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"σωφροσύνη\" data-meanings=\"autodomínio; castidade\">σωφροσύνη</span> (TestJos 10:2) IEph 10:3. Com outras virtudes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Tm 4.12</a>; 1 Cl 21:7; 64; Hs 9, 15, 2; Hm 6, 2, 3 (AcJ 29 [Aa II/1, 166, 24]; AcPh 3 [Aa II/2, 2, 30]; 37 [p. 18, 16]; AcThom 104 [Aa II/2, 217, 15]). Como primeiro dever da juventude, Pol 5:3; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν ἁ. μένειν\" data-meanings=\"permanecer em pureza; permanecer casto\">ἐν ἁ. μένειν</span>, “permanecer casto”, IPol 5:2 (AcPhil 119 [Aa II/2, 49, 3]). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν ἁ. κατοικεῖν\" data-meanings=\"viver em pureza\">ἐν ἁ. κατοικεῖν</span> Hm 4, 3, 2 (compare AcThom 131 [Aa II/2, 239, 2]); <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁ. φυλάσσειν\" data-meanings=\"guardar a pureza\">ἁ. φυλάσσειν</span> (compare Fílon, <em>Vi. Cont.</em> 68) 4, 1, 1 = <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁ. τηρεῖν\" data-meanings=\"manter a pureza\">ἁ. τηρεῖν</span> 4, 4, 3. — J. Müller, <em>D. Keuschheitsideen in ihrer gesch. Entwicklung</em> 1897; E. Fehrle, <em>D. kult. Keuschh. im Altertum</em> 1910, 42 ss. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅζομαι\" data-meanings=\"reverenciar\">ἅζομαι</span>. M-M. TW. Sv.\n</p></section></article><article id=\"entry-hagneuterion-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἁγνευτήριον</h1><div class=\"entry-meta\"><span class=\"greek\">ου, τό</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦hagneutḗrion⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁγνεύω\" data-meanings=\"ser puro\">ἁγνεύω</span>; Chaeremon Hist. [séc. I d.C.]: 618 Fgm. 6, p. 150, 9 Jac. = Porfírio, <em>De Abst.</em> 4, 6.) Literalmente <strong>“lugar de purificação”</strong>, talvez <strong>santuário</strong>, da parte do recinto do templo em que os <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅγια σκεύη\" data-meanings=\"vasos sagrados\">ἅγια σκεύη</span> eram guardados, Ox 840, 8; 13 (veja <em>Unknown Sayings</em> 37 n. 2; 41–43: “pátio interior, pátio dos israelitas”). — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅζομαι\" data-meanings=\"reverenciar\">ἅζομαι</span>. M-M s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁγνεία\" data-meanings=\"pureza\">ἁγνεία</span>.\n</p></section></article><article id=\"entry-hagneuo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἁγνεύω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦hagneúō⟧</span><span class=\"separator\">·</span><span class=\"greek\">fut. ἁγνεύσω</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Ésquilo, Heródoto e outros; inscrições; PRein 94, 22; PTebt 298, 68 [ambos séc. II d.C.]; Fílon; Jos., <em>Bell.</em> 5, 227; <em>Ant.</em> 14, 285.) <strong>Ser puro</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὑπὲρ τῆς ψυχῆς\" data-meanings=\"por causa de tua alma\">ὑπὲρ τῆς ψυχῆς</span>, “por causa de tua alma”, <span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"B 19:8\" data-tooltip-text=\"Epístola de Barnabé 19:8\">B 19:8</span> (compare Diod S 10, 9, 6 [<em>Exc. De Virt.</em> II 201 Vogel] <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τ. ψυχὴν ἁγνεύουσαν\" data-meanings=\"a alma que se mantém pura\">τ. ψυχὴν ἁγνεύουσαν</span>; Fílon, <em>Mut. Nom.</em> 44).\n</p></section></article>"};
